#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"//// Обработка кнопок//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~enum{  eTypeLeft=0,  eTypeRight=1,};// Структураtypedef struct : public SPROLOZ  {  COLORREF colorFill[2];  bool bHide0Show1;  int nType;  } Queue_Lodka;// Функция отображенияint PaintLodka(DefinePaint)  {  QueueP(Queue_Lodka);  //  RECT rc = p->mRect;  bool bBadValue=false;  int nNumber=-1;  CShHS* sh = (CShHS*)PipeSh;	if ( IsTypeOk )	{          if (p->bHide0Show1)          {              if ( sh->mOn )                nNumber = 0;          }          else          {              if ( sh->mOn )                nNumber = 1;              else                nNumber = 0;          }	}  if (nNumber==-1)  {     if ( ::GetMnemoStyle() & MNEMO_EDIT )     {       COLORREF clr=0x80ff;       CMyPen pen( hDC, clr );			 pen.Rect( rc );     }  }  else  {    int nWidthOfFigure=16;    int nShiftOfPoints=10;    COLORREF clrFill=p->colorFill[nNumber];    CMyPen pen( hDC, 0 );    CMyBrush brush(hDC, clrFill, true);    if (p->nType==eTypeRight)    {      if (nNumber==1)      {          POINT p0Array[]= {                    {p->mRect.left,p->mRect.top},                    {p->mRect.left+nWidthOfFigure, p->mRect.top+nShiftOfPoints},                    {p->mRect.left+nWidthOfFigure, p->mRect.bottom},                    {p->mRect.left, p->mRect.bottom},                  };                  brush.Points(p0Array,4,1);      }      else      {                  POINT p0Array[]= {                    {p->mRect.left,p->mRect.bottom},                    {p->mRect.left,p->mRect.bottom-nWidthOfFigure},                    {p->mRect.right,p->mRect.bottom-nWidthOfFigure},                    {p->mRect.right-nShiftOfPoints, p->mRect.bottom},                  };                  brush.Points(p0Array,4,1);      }    }    else    if (p->nType==eTypeLeft)    {      if (nNumber==1)      {          POINT p0Array[]= {                    {p->mRect.right,p->mRect.top},                    {p->mRect.right-nWidthOfFigure, p->mRect.top+nShiftOfPoints},                    {p->mRect.right-nWidthOfFigure, p->mRect.bottom},                    {p->mRect.right, p->mRect.bottom},                  };                  brush.Points(p0Array,4,1);      }      else      {                  POINT p0Array[]= {                    {p->mRect.right,p->mRect.bottom},                    {p->mRect.right,p->mRect.bottom-nWidthOfFigure},                    {p->mRect.left,p->mRect.bottom-nWidthOfFigure},                    {p->mRect.left+nShiftOfPoints, p->mRect.bottom},                  };                  brush.Points(p0Array,4,1);      }    }  }  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddLodka(DefineTegs)  {  //  AddQueueEx(Queue_Lodka);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintLodka;  //  //  p->colorFill[0]=0;  p->colorFill[1]=0;  p->nNumber=-1;  char szHsName[64]="";  p->bHide0Show1=false;  p->nType=eTypeLeft;  //  STegObj obj[] =    {	  { 'A', "color0" , &p->colorFill[0] },	  { 'A', "color1" , &p->colorFill[1] },	  { 'S', "hsName", szHsName, 63 },    { 'B', "hide0show1", &p->bHide0Show1},    { 'I', "type", &p->nType},    EXT_QUEUE  // Дополнительная информация    //    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  if (*szHsName)	  p->nNumber=def.AddKind( id_HS    , szHsName );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~